import{C as s,o as l,c as d,a2 as r,E as n,j as t,a as h}from"./chunks/framework.CFuv5BrO.js";const g=JSON.parse('{"title":"Delivery Overview","description":"Hearth delivery entry point: the product roadmap is the master outline, seven stage modules contain the work, and engineering safeguards cover verification, risk, and decisions.","frontmatter":{"title":"Delivery Overview","description":"Hearth delivery entry point: the product roadmap is the master outline, seven stage modules contain the work, and engineering safeguards cover verification, risk, and decisions.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/index.md","filePath":"en/delivery/index.md","lastUpdated":1793752688000}'),c={name:"en/delivery/index.md"},v=Object.assign(c,{setup(u){const i=[{no:"S0",meta:"4 increments",title:"Definition & Prototype",text:"Lock the user, task wedge, end-to-end prototype, contracts, and evaluation baseline.",link:"/en/delivery/stage-0"},{no:"S1",meta:"6 increments",title:"Durable Kernel & MVP",text:"Walking skeleton, first Codex slice, MVP-1, side-effect safety, and recovery.",link:"/en/delivery/stage-1"},{no:"S2",meta:"6 increments",title:"Personal Operator",text:"Connectors, documents and data, web research, and approval-gated writes.",link:"/en/delivery/stage-2"},{no:"S3",meta:"4 increments",title:"Computer Operator",text:"Desktop agentd, GUI observation, human takeover, and tiered desktop actions.",link:"/en/delivery/stage-3"},{no:"S4",meta:"5 increments",title:"Proactive Personal Agent",text:"Triggers, proactive inbox, mobile PWA, and attention budgets.",link:"/en/delivery/stage-4"},{no:"S5",meta:"4 increments",title:"Memory & Evolution",text:"Memory Core, forgetting and export, skill candidates, evaluation, and rollback.",link:"/en/delivery/stage-5"},{no:"S6",meta:"6 increments",title:"Multi-device & Operations",text:"Event sync, offline queues, device revocation, backup migration, and long-running operations.",link:"/en/delivery/stage-6"}],o=[{no:"01",title:"Engineering & Repository",text:"Tech stack, repository layout, process model, CLI, testing, and release migration.",link:"/en/delivery/engineering"},{no:"02",title:"Risks & Kill Criteria",text:"Pause conditions, stage Kill Criteria, and the foundations that must never be cut.",link:"/en/delivery/risks"},{no:"03",title:"ADRs & Key Decisions",text:"Judgments that are hard to reverse and the acceptance criteria for the final product exit.",link:"/en/delivery/decisions"}];return(p,e)=>{const a=s("DocCardGrid");return l(),d("div",null,[e[0]||(e[0]=r('<p class="eyebrow">DELIVERY MAP</p><h1 id="delivery-overview" tabindex="-1">Delivery Overview <a class="header-anchor" href="#delivery-overview" aria-label="Permalink to &quot;Delivery Overview&quot;">​</a></h1><p class="lead">The product roadmap defines scope, order, and stage gates. &quot;From 0 to 100&quot; turns that outline into seven independently buildable and verifiable modules. Engineering safeguards cover the repository, risk, and critical decisions.</p><blockquote><p><strong>There is one reading order:</strong> read the <a href="/hearth-os/en/delivery/roadmap.html">product roadmap</a> first to confirm what the current stage does and does not include; then enter the matching Stage module; finally review <a href="#engineering-safeguards">engineering safeguards</a> and <a href="/hearth-os/en/reference/source-map.html">source coverage</a>.</p></blockquote><h2 id="layer-1-the-product-roadmap-is-the-master-outline" tabindex="-1">Layer 1: The Product Roadmap Is the Master Outline <a class="header-anchor" href="#layer-1-the-product-roadmap-is-the-master-outline" aria-label="Permalink to &quot;Layer 1: The Product Roadmap Is the Master Outline&quot;">​</a></h2><p>The <a href="/hearth-os/en/delivery/roadmap.html">product roadmap</a> answers four questions:</p><ol><li><strong>Why this stage now?</strong> Sequence is driven by capability dependencies, not calendar estimates.</li><li><strong>What ships in this stage?</strong> The user-visible product form, core capabilities, and main risks are explicit.</li><li><strong>When is it complete?</strong> Every Stage has exit conditions and a learning gate.</li><li><strong>What are we deliberately not doing?</strong> High-risk, low-value, or foundation-damaging scope is deferred explicitly.</li></ol><p>Stages are capability gates, not date commitments. You may pause, trial, and roll back at any stage, but you cannot skip recovery, UI, verification, or security boundaries.</p><h2 id="layer-2-seven-development-modules" tabindex="-1">Layer 2: Seven Development Modules <a class="header-anchor" href="#layer-2-seven-development-modules" aria-label="Permalink to &quot;Layer 2: Seven Development Modules&quot;">​</a></h2><p>The From 0 to 100 Development Plan is not one broad checklist. It is seven sequential modules. Every module follows the same structure: prerequisites → development steps → increment breakdown → exit gates → out of scope. A developer can begin from the current module and build directly.</p>',10)),n(a,{items:i,columns:2}),e[1]||(e[1]=t("p",null,[t("a",{href:"/hearth-os/en/delivery/development-plan.html"},"Read the full development plan and delivery template")],-1)),e[2]||(e[2]=t("h2",{id:"layer-3-engineering-safeguards",tabindex:"-1"},[h("Layer 3: Engineering Safeguards "),t("a",{class:"header-anchor",href:"#layer-3-engineering-safeguards","aria-label":'Permalink to "Layer 3: Engineering Safeguards"'},"​")],-1)),e[3]||(e[3]=t("ul",null,[t("li",null,"Chapter 26 defines engineering implementation, and Chapter 27 defines risks and Kill Criteria."),t("li",null,"Chapter 28 summarizes ADR-001–020, and Chapter 29 provides terminology, default checklists, and the final judgment."),t("li",null,"The engineering foundation, recovery, security, and UI must not be cut to meet deadlines.")],-1)),n(a,{items:o,columns:3}),e[4]||(e[4]=r('<h2 id="stage-sequence" tabindex="-1">Stage Sequence <a class="header-anchor" href="#stage-sequence" aria-label="Permalink to &quot;Stage Sequence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Development module</th><th>Stage exit</th><th>Evidence that cannot be skipped</th></tr></thead><tbody><tr><td>Stage 0</td><td><a href="/hearth-os/en/delivery/stage-0.html">Definition &amp; Prototype</a></td><td>Clickable prototype and stable contracts</td><td>12 real tasks, complete state flow, evaluation and approval baseline</td></tr><tr><td>Stage 1</td><td><a href="/hearth-os/en/delivery/stage-1.html">Durable Kernel &amp; MVP</a></td><td>A locally usable daily MVP</td><td>Durable state, real Codex execution, approvals, artifacts, and recovery</td></tr><tr><td>Stage 2</td><td><a href="/hearth-os/en/delivery/stage-2.html">Personal Operator</a></td><td>Daily content work can be delegated</td><td>Connector loops, source citations, approval-gated writes, and receipts</td></tr><tr><td>Stage 3</td><td><a href="/hearth-os/en/delivery/stage-3.html">Computer Operator</a></td><td>Desktop work can run with takeover</td><td>GUI observation, takeover, isolation, desktop verification, high-risk approval</td></tr><tr><td>Stage 4</td><td><a href="/hearth-os/en/delivery/stage-4.html">Proactive Personal Agent</a></td><td>Proactive work within bounded authority</td><td>Triggers, attention budget, mobile approval, and instant pause</td></tr><tr><td>Stage 5</td><td><a href="/hearth-os/en/delivery/stage-5.html">Memory &amp; Evolution</a></td><td>Explainable and rollbackable accumulation</td><td>Memory correction/forgetting/export, skill evaluation, promotion, and rollback</td></tr><tr><td>Stage 6</td><td><a href="/hearth-os/en/delivery/stage-6.html">Multi-device &amp; Operations</a></td><td>A portable Personal Agent OS</td><td>Sync, offline recovery, device revocation, backup migration, and long-term audit</td></tr></tbody></table><p><strong>Where MVP Fits:</strong> MVP-1 is the early Stage 1 exit at D1.3, not a Stage 6 product. It must include real execution, durable tasks, Web task cards, artifacts, approval drills, and failure recovery.</p><h2 id="how-developers-should-start" tabindex="-1">How Developers Should Start <a class="header-anchor" href="#how-developers-should-start" aria-label="Permalink to &quot;How Developers Should Start&quot;">​</a></h2><ol><li>New to the project: read <a href="/hearth-os/en/guide/what-is-hearth.html">What is Hearth?</a> and the <a href="/hearth-os/en/product/definition.html">product definition</a>.</li><li>Ready to implement: read the <a href="/hearth-os/en/architecture/">system design overview</a> and <a href="/hearth-os/en/architecture/durable-execution.html">durable execution</a>.</li><li>Ready to build: open <a href="/hearth-os/en/delivery/stage-0.html">Stage 0</a> and complete its steps and increments in order.</li><li>Ready to merge: check <a href="/hearth-os/en/delivery/risks.html">Risks &amp; Kill Criteria</a> and the <a href="/hearth-os/en/reference/checklists.html">default checklists</a>.</li></ol><p>To confirm that every source document has a corresponding page, open <a href="/hearth-os/en/reference/source-map.html">Sources &amp; Coverage</a>.</p>',6))])}}});export{g as __pageData,v as default};
